package com.smartfitagent.mvc;
import com.smartfitagent.Json; import com.sun.net.httpserver.HttpExchange; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class Request { private final HttpExchange ex; public Request(HttpExchange ex){this.ex=ex;} public String path(){return ex.getRequestURI().getPath();} public String method(){return ex.getRequestMethod();} public String body() throws IOException{return new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);} public Map<String,String> json() throws IOException{return Json.parse(body());} public HttpExchange exchange(){return ex;} public String query(String key){String q=ex.getRequestURI().getRawQuery(); if(q==null)return""; for(String p:q.split("&")){String[] a=p.split("=",2); if(URLDecoder.decode(a[0],StandardCharsets.UTF_8).equals(key)) return a.length>1?URLDecoder.decode(a[1],StandardCharsets.UTF_8):"";} return "";} }
